--
-- Name: memo_proposals_guard(); Type: FUNCTION; Schema: tier1; Owner: -
--

CREATE FUNCTION tier1.memo_proposals_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- On tier2.transcripts' pattern, which refuses to re-attribute a row
        -- to another memo or model. Same reason: the identity is what makes
        -- the row mean anything, and a re-attributed proposal is a proposal
        -- credited to a model that never said it.
        IF NEW.memo_id  IS DISTINCT FROM OLD.memo_id
        OR NEW.proposer IS DISTINCT FROM OLD.proposer THEN
            RAISE EXCEPTION 'a proposal may not be re-attributed to another memo or proposer'
                USING ERRCODE = 'CH010';
        END IF;

        -- MONOTONE, like CHRN-22's audio_pruned_at. A generation that can go
        -- backwards is a generation an accept can be replayed against, which
        -- is the drift this column exists to close.
        IF NEW.generation < OLD.generation THEN
            RAISE EXCEPTION 'proposal generation may not decrease (% -> %)',
                OLD.generation, NEW.generation
                USING ERRCODE = 'CH011';
        END IF;

        NEW.updated_at := now();
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: memo_links_guard(); Type: FUNCTION; Schema: tier2; Owner: -
--

CREATE FUNCTION tier2.memo_links_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- On tier1.memo_proposals' pattern and tier2.transcripts' before it: the
    -- identity is what makes the row mean anything, and a re-attributed
    -- decision is a decision credited to a memo nobody made it about.
    IF NEW.memo_id IS DISTINCT FROM OLD.memo_id THEN
        RAISE EXCEPTION 'a memo link may not be re-attributed to another memo'
            USING ERRCODE = 'CH020';
    END IF;

    -- CONFIRMED IS TERMINAL, and this is load-bearing rather than tidy.
    --
    -- The accept path answers `applied` with the stored key for a memo that is
    -- already triaged, and it does that WITHOUT an outward call. That answer is
    -- only honest while a confirmation cannot be withdrawn — if a later sweep
    -- or a later batch could un-confirm a row, the key an operator was told
    -- about could stop being the ticket their memo became, and nothing would
    -- have logged the change.
    IF OLD.confirmed_at IS NOT NULL
       AND (NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at
            OR NEW.ticket_key IS DISTINCT FROM OLD.ticket_key
            OR NEW.destination IS DISTINCT FROM OLD.destination) THEN
        RAISE EXCEPTION 'a confirmed memo link is immutable (memo %)', OLD.memo_id
            USING ERRCODE = 'CH021';
    END IF;

    -- RE-ARMING A REFUSED ROW MUST BE A WHOLE NEW DECISION.
    --
    -- A refusal is an outcome, and the row keeps it so the operator can be told
    -- why. Clearing `refused_at` is how a corrected decision reclaims the row —
    -- but a corrected decision that re-sent the SAME idempotency key would
    -- replay the cached refusal it was correcting, which is the twenty-four
    -- hour trap `sent_idempotency_key` exists to close. Re-arming without a
    -- fresh key is therefore refused here, where it cannot be forgotten,
    -- rather than left to the one code path that does it today.
    IF OLD.refused_at IS NOT NULL AND NEW.refused_at IS NULL
       AND NEW.sent_idempotency_key = OLD.sent_idempotency_key THEN
        RAISE EXCEPTION 're-arming a refused memo link needs a fresh idempotency key (memo %)', OLD.memo_id
            USING ERRCODE = 'CH022';
    END IF;

    NEW.updated_at := now();
    RETURN NEW;
END
$$;


--
-- Name: memos_guard(); Type: FUNCTION; Schema: tier2; Owner: -
--

CREATE FUNCTION tier2.memos_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- One entry point. A memo exists only once its audio is complete and
    -- durable, so there is no state meaning "maybe there are bytes".
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'captured' THEN
            RAISE EXCEPTION 'memo must be created in state captured, got %', NEW.state
                USING ERRCODE = 'CH003';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.author_id    IS DISTINCT FROM OLD.author_id
    OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
    OR NEW.byte_size    IS DISTINCT FROM OLD.byte_size
    OR NEW.captured_at  IS DISTINCT FROM OLD.captured_at THEN
        RAISE EXCEPTION 'memo identity and captured_at are immutable'
            USING ERRCODE = 'CH002';
    END IF;

    -- 'discarded' appears only as a target and never as a source: that is how
    -- terminal is written down, where it can be read. 'held' keeps an exit to
    -- 'queued' even after its audio prunes, which is why a worker claiming a
    -- memo that already has a durable transcript must skip ASR (E3) rather
    -- than reach for bytes that are gone.
    IF NEW.state IS DISTINCT FROM OLD.state
       AND (OLD.state || '>' || NEW.state) <> ALL (ARRAY[
             'captured>queued',          'captured>held',      'captured>discarded',
             'queued>transcribing',      'queued>held',        'queued>discarded',
             'transcribing>transcribed', 'transcribing>queued',
             'transcribing>held',        'transcribing>discarded',
             'transcribed>triaged',      'transcribed>held',   'transcribed>discarded',
             'triaged>held',             'triaged>discarded',
             'held>queued',              'held>discarded'
       ]) THEN
        RAISE EXCEPTION 'illegal memo state transition % -> %', OLD.state, NEW.state
            USING ERRCODE = 'CH001';
    END IF;

    NEW.updated_at := now();
    RETURN NEW;
END
$$;


--
-- Name: note_deletions_guard(); Type: FUNCTION; Schema: tier2; Owner: -
--

CREATE FUNCTION tier2.note_deletions_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'a deletion record is not removable'
            USING ERRCODE = 'CH070';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        -- The only legal UPDATE is closing an open record out.
        IF NEW.id         IS DISTINCT FROM OLD.id
        OR NEW.note_id    IS DISTINCT FROM OLD.note_id
        OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
        OR NEW.deleted_by IS DISTINCT FROM OLD.deleted_by THEN
            RAISE EXCEPTION 'a deletion record is immutable except for being closed out'
                USING ERRCODE = 'CH070';
        END IF;
        IF OLD.undeleted_at IS NOT NULL THEN
            RAISE EXCEPTION 'that deletion record is already closed'
                USING ERRCODE = 'CH070';
        END IF;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM tier2.users
                    WHERE id = NEW.deleted_by AND kind = 'person') THEN
        RAISE EXCEPTION 'a note is deleted by a person, not by an agent'
            USING ERRCODE = 'CH041';
    END IF;
    IF NEW.undeleted_by IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM tier2.users
                     WHERE id = NEW.undeleted_by AND kind = 'person') THEN
        RAISE EXCEPTION 'a note is undeleted by a person, not by an agent'
            USING ERRCODE = 'CH041';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: note_revisions_guard(); Type: FUNCTION; Schema: tier2; Owner: -
