    CONSTRAINT memo_links_confirmed_xor_refused CHECK (((confirmed_at IS NULL) OR (refused_at IS NULL))),
    CONSTRAINT memo_links_destination_check CHECK ((destination = ANY (ARRAY['NOTE'::text, 'TICKET'::text, 'DISCUSSION'::text, 'DISCARD'::text]))),
    CONSTRAINT memo_links_refusal_states_why CHECK (((refused_at IS NULL) = (refused_reason IS NULL))),
    CONSTRAINT memo_links_sent_idempotency_key_check CHECK ((sent_idempotency_key <> ''::text)),
    CONSTRAINT memo_links_ticket_key_only_on_ticket CHECK (((ticket_key IS NULL) OR (destination = 'TICKET'::text)))
);


--
-- Name: TABLE memo_links; Type: COMMENT; Schema: tier2; Owner: -
--

COMMENT ON TABLE tier2.memo_links IS 'What a PERSON decided a memo becomes. Authored, not derived: nothing regenerates it. UNIQUE (memo_id) is the lock that keeps one memo from becoming two tickets.';


--
-- Name: memos; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.memos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    author_id uuid NOT NULL,
    content_hash text NOT NULL,
    byte_size bigint NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    state text DEFAULT 'captured'::text NOT NULL,
    state_reason text,
    retention text DEFAULT 'days_30'::text NOT NULL,
    audio_pruned_at timestamp with time zone,
    duration_ms integer,
    codec text,
    sample_rate_hz integer,
    original_filename text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT memos_byte_size_check CHECK ((byte_size > 0)),
    CONSTRAINT memos_content_hash_check CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT memos_duration_ms_check CHECK (((duration_ms IS NULL) OR (duration_ms > 0))),
    CONSTRAINT memos_retention_check CHECK ((retention = ANY (ARRAY['discard_now'::text, 'days_30'::text, 'forever'::text]))),
    CONSTRAINT memos_state_check CHECK ((state = ANY (ARRAY['captured'::text, 'queued'::text, 'transcribing'::text, 'transcribed'::text, 'triaged'::text, 'held'::text, 'discarded'::text])))
);


--
-- Name: note_deletions; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.note_deletions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    note_id uuid NOT NULL,
    deleted_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_by uuid NOT NULL,
    undeleted_at timestamp with time zone,
    undeleted_by uuid,
    CONSTRAINT note_deletions_undeleted_pair CHECK (((undeleted_at IS NULL) = (undeleted_by IS NULL)))
);


--
-- Name: TABLE note_deletions; Type: COMMENT; Schema: tier2; Owner: -
--

COMMENT ON TABLE tier2.note_deletions IS 'CHRN-39, ruling 5. One row per deletion of a note, closed out on undelete. Tier 2 — a record of a person''s act on authored text, regenerable from nothing. tier2.notes.deleted_at is the current state; this is the history.';


--
-- Name: note_number_seq; Type: SEQUENCE; Schema: tier2; Owner: -
--

CREATE SEQUENCE tier2.note_number_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: note_revisions; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.note_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    note_id uuid NOT NULL,
    seq integer NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    memo_id uuid,
    author_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_by uuid,
    verb text,
    restored_from uuid,
    CONSTRAINT note_revisions_seq_check CHECK ((seq > 0)),
    CONSTRAINT note_revisions_verb CHECK (((verb IS NULL) OR (verb = ANY (ARRAY['create'::text, 'append'::text, 'supersede'::text, 'relate'::text])))),
    CONSTRAINT note_revisions_verb_seq CHECK (((verb IS NULL) OR ((seq = 1) = (verb = ANY (ARRAY['create'::text, 'relate'::text])))))
);


--
-- Name: COLUMN note_revisions.confirmed_by; Type: COMMENT; Schema: tier2; Owner: -
--

COMMENT ON COLUMN tier2.note_revisions.confirmed_by IS 'CHRN-39. Who agreed to this text landing — never an agent, enforced by CH041. Distinct from author_id, which is whose words these are and may legitimately be an agent. NULL only on rows written before 0014.';


--
-- Name: COLUMN note_revisions.verb; Type: COMMENT; Schema: tier2; Owner: -
--

COMMENT ON COLUMN tier2.note_revisions.verb IS 'CHRN-39. What a person confirmed about a Scribe proposal: create, append, supersede or relate. NULL means authored directly.';


--
-- Name: COLUMN note_revisions.restored_from; Type: COMMENT; Schema: tier2; Owner: -
--

COMMENT ON COLUMN tier2.note_revisions.restored_from IS 'CHRN-39. The revision this one was restored from. A restore APPENDS rather than rewinding (ruling 1), so this is what distinguishes a restore from an ordinary edit that happens to reproduce old text.';


--
-- Name: note_tags; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.note_tags (
    note_id uuid NOT NULL,
    tag text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT note_tags_tag_check CHECK ((tag ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);


--
-- Name: notes; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    number bigint DEFAULT nextval('tier2.note_number_seq'::regclass) NOT NULL,
    page_id uuid NOT NULL,
    current_revision_id uuid NOT NULL,
    author_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT notes_deleted_pair CHECK (((deleted_at IS NULL) = (deleted_by IS NULL)))
);


--
-- Name: page_redirects; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.page_redirects (
    from_path text NOT NULL,
    page_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT page_redirects_from_path_check CHECK ((from_path <> ''::text))
);


--
-- Name: pages; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.pages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parent_id uuid,
    slug text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pages_slug_check CHECK ((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);


--
-- Name: transcripts; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.transcripts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    memo_id uuid NOT NULL,
    text text NOT NULL,
    segments jsonb DEFAULT '[]'::jsonb NOT NULL,
    partial boolean NOT NULL,
    model text NOT NULL,
    backend text NOT NULL,
    audio_duration_ms bigint,
    covered_ms bigint,
    transcribed_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE transcripts; Type: COMMENT; Schema: tier2; Owner: -
--

COMMENT ON TABLE tier2.transcripts IS 'CHRN-27. What a memo said. Tier 2 — it outlives the audio CHRN-22 prunes at thirty days, and nothing regenerates it once that audio is gone. `partial` is the gate that pruner reads: durable iff a run completed and partial is false. Empty text with a completed run IS durable.';


--
-- Name: user_tokens; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.user_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    token_hash text NOT NULL,
    label text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone,
    used_at timestamp with time zone,
    expires_at timestamp with time zone,
    CONSTRAINT user_tokens_kind_check CHECK ((kind = ANY (ARRAY['invite'::text, 'session'::text])))
);


--
-- Name: users; Type: TABLE; Schema: tier2; Owner: -
--

CREATE TABLE tier2.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    display_name text NOT NULL,
    kind text DEFAULT 'person'::text NOT NULL,
    is_owner boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT users_kind_check CHECK ((kind = ANY (ARRAY['person'::text, 'agent'::text]))),
    CONSTRAINT users_owner_is_a_person CHECK (((NOT is_owner) OR (kind = 'person'::text)))
);


